        s_d=1 if di>0 else -1
        s_j=1 if dj>0 else -1
        if DISP[c]==(-1,2):
            # L: horizontal first from (i,j) to j+dj, then vertical to i+di
            for cc in range(j,j+dj,s_j): paint(i,cc,5)
            for rr in range(i,i+di,s_d): paint(rr,j+dj,5)
        elif DISP[c]==(0,-4) or DISP[c]==(3,0) or DISP[c]==(-6,0):
