            elif DISP[c]==(-6,0): cells=[(rr,j) for rr in range(i-1,i-7)]
            else: cells=[(i,cc) for cc in range(j-1,j-5)]
            paint(*cells[0],5)
            for rr,cc in cells: paint(rr,cc,5)
    # crossing detection & 4 diagonal
    # beams: compute per-color ray segments
    segs=[]
    for c in colors:
        if c==0: continue
        i,j=next(p for p in pts if g[p[0]][p[1]]==c)
        di,dj=DISP[c]; s_d=1 if di>0 else -1; s_j=1 if dj>0 else -1
        cells=[]
        if DISP[c]==(-1,2):
            cells+= [(i,cc) for cc in range(j,j+3,s_j)]
            cells+= [(rr,j+2) for rr in range(i,i-1,s_d)]
        elif DISP[c]==(3,0): cells=[(rr,j) for rr in range(i+1,i+4)]
        elif DISP[c]==(-6,0): cells=[(rr,j) for rr in range(i-1,i-7)]
        else: cells=[(i,cc) for cc in range(j-1,j-5)]
        segs.append((c,cells))
    # find crossing between any two segments
    crossing=None
    for a,b in segs:
        for ca,pa in a:
            for cb,pb in b:
                if ca!=cb and pa[0]==pb[0] and pa[1]==pb[1]: crossing=pa
    if crossing:
        out[crossing[0]][crossing[1]]=4
        r,cx=crossing
        for k in range(1,11):
            rr,cc=r+k,cx-k
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=4
            else: break
    return out
